// Generated from sequeless-spi-testkit/src/main/resources/ontology/reference.ttl. Do not edit by hand.
export const REFERENCE_TTL = "@prefix ex:   <https://sequeless.dev/ns/ref#> .\n@prefix sq:   <https://sequeless.dev/ns/meta#> .\n@prefix owl:  <http://www.w3.org/2002/07/owl#> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .\n@prefix sh:   <http://www.w3.org/ns/shacl#> .\n\n#\n# Reference-domain ontology used across the contract testkit and the Jena adapter's own tests.\n# Deliverable is abstract and superclasses WorkItem, which is itself abstract and superclasses the\n# concrete Task and Project types. Person stands alone. The three-level hierarchy is intentional:\n# it is what makes the reasoner=none / rdfs / owl distinction on superTypes() observable.\n#\n# status (on WorkItem), priority/dueDate (on Task), and name (on Person) each carry an explicit\n# owl:maxCardinality 1 restriction (T13): DefaultBusinessObjectService's filter/sort/facet\n# resolution and PostgresQueryStore's per-datatype JSONB extraction both require a scalar\n# (cardinality max 1) property, since ValueCoercer stores anything else as a JSON list rather than\n# a bare tagged value. Without this, filtering/sorting/faceting on these properties through the\n# REST API (and the assignedTo facet's Person.name display-label resolution, which reads target.\n# props ->> 'text' the same way) is unreachable even though the property itself is sq:facet/\n# sq:indexed. estimatedHours (on Task) gained the same restriction in Phase 4 (derived properties,\n# T5): ex:totalEstimatedHours below is a sq:Rollup that sums it with SQL sum(), which needs\n# ValueCoercer to have stored a bare tagged value ({\"decimal\": ...}) rather than a JSON list, for\n# exactly the reason filter/sort/facet resolution does above. title/description remain\n# deliberately unrestricted (max unbounded) — nothing filters/sorts/facets/aggregates on them, and\n# existing tests (F39) rely on posting them as JSON lists.\n#\n# ex:Project also declares two Phase 4 derived properties, openTaskCount and totalEstimatedHours:\n# both are sq:Rollup-derived, computed on read from ex:Task via ex:belongsToProject, and never\n# stored in props. Declaring sq:derivedBy forces PropertyDefinition.readOnly() true regardless of\n# sq:readOnly, and both carry an owl:maxCardinality 1 restriction so they render as scalars, the\n# same way status does above. See docs/architecture/sq-vocabulary.md for the sq:Rollup vocabulary.\n#\n\n<https://sequeless.dev/ns/ref>\n    a owl:Ontology ;\n    owl:imports <https://sequeless.dev/ns/meta> .\n\n#\n# Classes\n#\n\nex:Deliverable\n    a owl:Class ;\n    sq:label \"Deliverable\" ;\n    sq:abstract \"true\"^^xsd:boolean .\n\nex:WorkItem\n    a owl:Class ;\n    rdfs:subClassOf ex:Deliverable ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:status ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ;\n    sq:label \"Work Item\" ;\n    sq:abstract \"true\"^^xsd:boolean .\n\nex:Task\n    a owl:Class ;\n    rdfs:subClassOf ex:WorkItem ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:title ;\n          owl:minCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:assignedTo ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:priority ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:dueDate ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:estimatedHours ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ;\n    sq:label \"Task\" .\n\nex:Project\n    a owl:Class ;\n    rdfs:subClassOf ex:WorkItem ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:openTaskCount ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:totalEstimatedHours ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:owner ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ;\n    sq:label \"Project\" .\n\nex:Person\n    a owl:Class ;\n    rdfs:subClassOf\n        [ a owl:Restriction ;\n          owl:onProperty ex:name ;\n          owl:minCardinality \"1\"^^xsd:nonNegativeInteger ] ,\n        [ a owl:Restriction ;\n          owl:onProperty ex:name ;\n          owl:maxCardinality \"1\"^^xsd:nonNegativeInteger ] ;\n    sq:label \"Person\" .\n\n#\n# Properties\n#\n\nex:title\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Deliverable ;\n    rdfs:range xsd:string ;\n    sq:label \"Title\" ;\n    sq:searchable \"true\"^^xsd:boolean ;\n    sq:displayLabel \"true\"^^xsd:boolean ;\n    sq:displayGroup \"General\" ;\n    sq:displayOrder \"1\"^^xsd:integer .\n\nex:status\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:WorkItem ;\n    rdfs:range xsd:string ;\n    sq:label \"Status\" ;\n    sq:facet \"true\"^^xsd:boolean ;\n    sq:indexed \"true\"^^xsd:boolean ;\n    sq:displayOrder \"2\"^^xsd:integer .\n\nex:priority\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Task ;\n    rdfs:range xsd:integer ;\n    sq:label \"Priority\" ;\n    sq:displayGroup \"Planning\" ;\n    sq:displayOrder \"3\"^^xsd:integer .\n\nex:createdAt\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Deliverable ;\n    rdfs:range xsd:dateTime ;\n    sq:label \"Created At\" ;\n    sq:hidden \"true\"^^xsd:boolean ;\n    sq:readOnly \"true\"^^xsd:boolean ;\n    sq:displayOrder \"6\"^^xsd:integer .\n\nex:estimatedHours\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Task ;\n    rdfs:range xsd:decimal ;\n    sq:label \"Estimated Hours\" ;\n    sq:displayOrder \"7\"^^xsd:integer .\n\nex:dueDate\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Task ;\n    rdfs:range xsd:date ;\n    sq:label \"Due Date\" ;\n    sq:displayOrder \"8\"^^xsd:integer .\n\nex:description\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:WorkItem ;\n    rdfs:range xsd:string ;\n    sq:label \"Description\" ;\n    sq:searchable \"true\"^^xsd:boolean ;\n    sq:displayGroup \"General\" ;\n    sq:displayOrder \"9\"^^xsd:integer .\n\nex:assignedTo\n    a owl:ObjectProperty ;\n    rdfs:domain ex:Task ;\n    rdfs:range ex:Person ;\n    sq:label \"Assigned To\" ;\n    sq:facet \"true\"^^xsd:boolean ;\n    sq:displayOrder \"4\"^^xsd:integer .\n\nex:belongsToProject\n    a owl:ObjectProperty ,\n        owl:FunctionalProperty ;\n    rdfs:domain ex:Task ;\n    rdfs:range ex:Project ;\n    owl:inverseOf ex:hasTask ;\n    sq:label \"Belongs To Project\" ;\n    sq:displayOrder \"5\"^^xsd:integer .\n\nex:hasTask\n    a owl:ObjectProperty ;\n    rdfs:domain ex:Project ;\n    rdfs:range ex:Task ;\n    sq:label \"Has Task\" ;\n    sq:displayOrder \"2\"^^xsd:integer .\n\nex:owner\n    a owl:ObjectProperty ;\n    rdfs:domain ex:Project ;\n    rdfs:range ex:Person ;\n    sq:label \"Owner\" ;\n    sq:displayOrder \"6\"^^xsd:integer .\n\nex:name\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Person ;\n    rdfs:range xsd:string ;\n    sq:label \"Name\" ;\n    sq:displayLabel \"true\"^^xsd:boolean ;\n    sq:displayOrder \"1\"^^xsd:integer .\n\nex:email\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Person ;\n    rdfs:range xsd:string ;\n    sq:label \"Email\" ;\n    sq:displayOrder \"2\"^^xsd:integer .\n\n#\n# Derived properties (Phase 4, DR-08) — computed on read from ex:Task, never stored in props.\n# ex:openTaskCount is additionally sq:materialised (Phase 6): its value is *also* kept correct in\n# sq_object.props from domain events, so it is filterable/sortable (filter[openTaskCount][eq]=0),\n# while GET/browse still always return the freshly recomputed aggregate above, never the stored\n# value. ex:totalEstimatedHours is deliberately left non-materialised, to exercise the 400\n# rejection path for filtering/sorting an un-materialised derived property.\n#\n\nex:openTaskCount\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Project ;\n    rdfs:range xsd:integer ;\n    sq:label \"Open Tasks\" ;\n    sq:displayOrder \"3\"^^xsd:integer ;\n    sq:derivedBy [\n        a sq:Rollup ;\n        sq:function sq:count ;\n        sq:over ex:Task ;\n        sq:via ex:belongsToProject ;\n        sq:filter ( [ a sq:Criterion ;\n                      sq:property ex:status ;\n                      sq:operator sq:ne ;\n                      sq:value \"done\" ] ) ;\n        sq:materialised true ] .\n\nex:totalEstimatedHours\n    a owl:DatatypeProperty ;\n    rdfs:domain ex:Project ;\n    rdfs:range xsd:decimal ;\n    sq:label \"Total Estimated Hours\" ;\n    sq:displayOrder \"4\"^^xsd:integer ;\n    sq:derivedBy [\n        a sq:Rollup ;\n        sq:function sq:sum ;\n        sq:over ex:Task ;\n        sq:via ex:belongsToProject ;\n        sq:of ex:estimatedHours ] .\n\n#\n# State machine (Phase 5, DR-09; automated triggers added Phase 6, DR-11) — ex:Project moves\n# Draft -> Active -> OnHold/Closed, plus Closed -> Active. `activate`, `hold`, `resume`, and\n# `close` are sq:UserAction, fired only by a REST caller. `activate` is the only transition with a\n# guard (self.owner != null) and the only one with actions, so it exercises both mechanisms an\n# ExpressionPort implementation (a later task) must support: sq:expression on\n# sq:SetProperty/sq:PropertyAssignment nodes is bare JEXL source (no ${} — the whole string is the\n# expression), while sq:url/sq:body on sq:Webhook are JXLT templates (${expr} placeholders spliced\n# into an otherwise-literal string). `hold`, `resume`, and `close` deliberately carry no sq:guard,\n# to exercise the \"always available\" path.\n#\n# The three remaining transitions each exercise one of the other three sq:trigger kinds and fire\n# without any user request, through the same guard -> commit -> action path `fire` uses:\n#   - `autoClose` (sq:OnChange, sq:watch ex:belongsToProject) reacts to any ex:Task that points\n#     back at this ex:Project changing, and moves Active -> Closed once self.openTaskCount == 0 —\n#     the very reason ex:openTaskCount is sq:materialised above, since the guard reads it from\n#     stored props, not by recomputing it inline.\n#   - `expireHold` (sq:Timer, sq:after \"PT72H\") moves OnHold -> Closed 72 hours after the object\n#     entered OnHold; the duration is ontology data, editable without a rebuild.\n#   - `reopen` (sq:ExternalSignal, sq:signalName \"reopen\") moves Closed -> Active in response to a\n#     POST /objects/Project/{id}/signals/reopen call naming that signal.\n#\n# Every expression here only reaches into the ExpressionContext shape a later task will define\n# (self's own properties, self's current state, and the acting principal) — e.g. self.owner,\n# self.title, self.openTaskCount — never a property (like self.id) that shape won't carry.\n#\n\nex:ProjectLifecycle\n    a sq:StateMachine ;\n    sq:appliesTo ex:Project ;\n    sq:initialState ex:Draft ;\n    sq:state ex:Draft, ex:Active, ex:OnHold, ex:Closed ;\n    sq:transition\n        [ a sq:Transition ;\n          sq:name \"activate\" ;\n          sq:from ex:Draft ; sq:to ex:Active ;\n          sq:trigger sq:UserAction ;\n          sq:guard \"self.owner != null\" ;\n          sq:guardMessage \"Project must have an owner before it can be activated\" ;\n          sq:action\n            ( [ a sq:CreateObject ;\n                sq:type ex:Task ;\n                sq:properties\n                  ( [ a sq:PropertyAssignment ;\n                      sq:property ex:title ;\n                      sq:expression \"'Kickoff: ' + self.title\" ] ) ]\n              [ a sq:Webhook ;\n                sq:url \"https://example.org/hooks/project-activated\" ;\n                sq:method \"POST\" ;\n                sq:body \"{\\\"project\\\": \\\"${self.title}\\\"}\" ] ) ] ,\n        [ a sq:Transition ; sq:name \"hold\" ;   sq:from ex:Active ; sq:to ex:OnHold ; sq:trigger sq:UserAction ] ,\n        [ a sq:Transition ; sq:name \"resume\" ; sq:from ex:OnHold ; sq:to ex:Active ; sq:trigger sq:UserAction ] ,\n        [ a sq:Transition ; sq:name \"close\" ;  sq:from ex:Active ; sq:to ex:Closed ; sq:trigger sq:UserAction ] ,\n        [ a sq:Transition ; sq:name \"autoClose\" ;\n          sq:from ex:Active ; sq:to ex:Closed ;\n          sq:trigger sq:OnChange ; sq:watch ex:belongsToProject ;\n          sq:guard \"self.openTaskCount == 0\" ;\n          sq:guardMessage \"Project still has open tasks\" ] ,\n        [ a sq:Transition ; sq:name \"expireHold\" ;\n          sq:from ex:OnHold ; sq:to ex:Closed ;\n          sq:trigger sq:Timer ; sq:after \"PT72H\" ] ,\n        [ a sq:Transition ; sq:name \"reopen\" ;\n          sq:from ex:Closed ; sq:to ex:Active ;\n          sq:trigger sq:ExternalSignal ; sq:signalName \"reopen\" ] .\n\nex:Draft  a sq:State ; sq:label \"Draft\"   ; sq:displayOrder \"1\"^^xsd:integer .\nex:Active a sq:State ; sq:label \"Active\"  ; sq:displayOrder \"2\"^^xsd:integer .\nex:OnHold a sq:State ; sq:label \"On Hold\" ; sq:displayOrder \"3\"^^xsd:integer .\nex:Closed a sq:State ; sq:label \"Closed\"  ; sq:displayOrder \"4\"^^xsd:integer .\n\n#\n# SHACL shapes\n#\n\nex:TaskShape\n    a sh:NodeShape ;\n    sh:targetClass ex:Task ;\n    sh:property [\n        sh:path ex:estimatedHours ;\n        sh:minInclusive 0 ;\n        sh:maxInclusive 1000 ;\n    ] .\n\nex:PersonShape\n    a sh:NodeShape ;\n    sh:targetClass ex:Person ;\n    sh:property [\n        sh:path ex:email ;\n        sh:pattern \"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\" ;\n    ] .\n";

